import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const ROOT = process.cwd();
const sourcePath = resolve(ROOT, 'projects/icons-angular/src/lib/generated/icon-manifest.json');
const outputPath = resolve(ROOT, 'projects/icons-react/src/generated/icon-manifest.ts');

const sourceRaw = await readFile(sourcePath, 'utf8');
const source = JSON.parse(sourceRaw);
const icons = source.icons ?? [];

const fileContent = `/* eslint-disable */
/* istanbul ignore file */
// Auto-generated by tools/generate-react-manifest.mjs. Do not edit manually.

import type { IconRegistration } from '@weibook/icon-core';

export const WB_ICON_MANIFEST: IconRegistration[] = ${JSON.stringify(icons, null, 2)};\n`;

await mkdir(resolve(ROOT, 'projects/icons-react/src/generated'), { recursive: true });
await writeFile(outputPath, fileContent, 'utf8');

console.log(`React manifest generated with ${icons.length} icons.`);
